//! Delete only the two generic targets generated by keyring 3's default Windows backend.
use std::path::Path;
use tauri::Manager;
const TARGETS: [&str; 2] = ["anthropic-admin.tuck", "openai-admin.tuck"];

fn cleanup(marker: &Path, mut delete: impl FnMut(&str) -> bool) -> std::io::Result<()> {
    if marker.exists() {
        return Ok(());
    }
    for target in TARGETS {
        if !delete(target) {
            eprintln!("Legacy credential cleanup failed");
        }
    }
    if let Some(parent) = marker.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(marker, b"1")
}

pub(crate) fn run(app: &tauri::AppHandle) {
    let result =
        app.path().app_data_dir().map_err(|_| ()).and_then(|dir| {
            cleanup(&dir.join("legacy-credentials-v1.done"), delete).map_err(|_| ())
        });
    if result.is_err() {
        eprintln!("Legacy credential cleanup failed");
    }
}

#[cfg(windows)]
fn delete(target: &str) -> bool {
    use windows::Win32::Security::Credentials::{CredDeleteW, CRED_TYPE_GENERIC};
    let target: Vec<u16> = target.encode_utf16().chain(Some(0)).collect();
    // No read or enumeration: CredDeleteW identifies a generic credential by its exact target.
    match unsafe { CredDeleteW(windows::core::PCWSTR(target.as_ptr()), CRED_TYPE_GENERIC, 0) } {
        Ok(()) => true,
        Err(error) => error.code() == windows::core::HRESULT::from_win32(1168),
    }
}
#[cfg(not(windows))]
fn delete(_: &str) -> bool {
    true
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn exact_targets_once_even_when_deletion_fails() {
        let dir = std::env::temp_dir().join(format!("tuck-cleanup-{}", uuid::Uuid::new_v4()));
        let marker = dir.join("done");
        let mut calls = Vec::new();
        cleanup(&marker, |name| {
            calls.push(name.to_owned());
            false
        })
        .unwrap();
        assert_eq!(calls, TARGETS);
        cleanup(&marker, |_| panic!("must not repeat")).unwrap();
        std::fs::remove_dir_all(dir).unwrap();
    }
}
